class Solution {
public:
    vector<int> largestSubarray(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> best(nums.begin(), nums.begin() + k);
        for (int i = 1; i + k <= n; ++i)
            if (vector<int>(nums.begin() + i, nums.begin() + i + k) > best)
                best.assign(nums.begin() + i, nums.begin() + i + k);
        return best;
    }
};

