class Solution {
    public int[] largestSubarray(int[] nums, int k) {
        int n = nums.length, bestStart = 0;
        for (int i = 1; i + k <= n; i++)
            for (int j = 0; j < k; j++) {
                if (nums[i + j] != nums[bestStart + j]) {
                    if (nums[i + j] > nums[bestStart + j]) bestStart = i;
                    break;
                }
            }
        return Arrays.copyOfRange(nums, bestStart, bestStart + k);
    }
}

